// Engineering synthesis, discipline screens and import wizard view models against the prototype's own render values
// (eng.golden.json, generated by scripts/proto-golden-eng.ts from design lines 3096–5239, renderValsEN and renderVals
// in French) on the seeded in-memory database — the register read by the data layer (getEngineeringRegister), the
// deliverables from the Codex index — in EN and FR: the default state, then every step of the generator's sequence
// replayed with the data-layer writers (confirm, resolve / send back, import, freeze / propose / validate, generate)
// on one database, compared after each step. Also the template labels and their French. Deliberate deviations are
// listed in EN_FIX / FR_FIX and applied to the golden values before comparing.
import { beforeAll, describe, expect, it } from 'vitest';
import { makeT, trFR, type Lang } from '@/i18n/translate';
import { getDb, setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import { CODEX_TODAY_ISO, parisParts, type Discipline } from '@/server/db/codes';
import { getDocumentRecord, recordDocumentDecision } from '@/server/dal/documents';
import { applyCodexDocumentStates } from '@/server/integrations/codex/mirror';
import { getEngScreen } from '@/server/dal/eng-screen';
import {
  closeEngCheck, confirmEngInput, freezeEngDeliverable, generateEngOutput, importEngList, proposeEngRelease, validateEngRelease, type Actor,
} from '@/server/dal/engineering';
import { primaryImportTarget, type EngRegister, type EngScreen } from '@/domain/engineering';
import GOLD from './eng.golden.json';
import { frSingular } from './i18n';
import { disciplineScreenView, importWizardModel, synthesisScreenView } from './model';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const HLT = 'HLT-026';
const LANGS: Lang[] = ['en', 'fr'];
const DISCS: Discipline[] = ['process', 'meca', 'elec', 'auto'];
const DIRECTOR: Actor = { name: 'Marie Lefebvre', role: 'director' };

/** Deliberate deviations: the singular gate tag (EN, FR), the prototype's broken French note, French singulars after "1". */
const EN_FIX: Record<string, string> = { 'Blocked by 1 blocking inconsistencies': 'Blocked by 1 blocking inconsistency' };
const FR_FIX: Record<string, string> = {
  'Envoyé le back to tool · closes on next import': 'Renvoyé vers l’outil · se clôt au prochain import',
  'Bloqué par 1 incohérences bloquantes': 'Bloqué par 1 incohérence bloquante',
};
const fix = (lang: Lang, s: string) => (lang === 'fr' ? frSingular(FR_FIX[s] ?? s) : (EN_FIX[s] ?? s));
const fixDeep = (lang: Lang, x: any): any => JSON.parse(JSON.stringify(x), (_k, v) => (typeof v === 'string' ? fix(lang, v) : v));
const parisDay = (iso: string) => parisParts(new Date(iso)).iso;
const omit = <O extends object>(o: O, ...keys: string[]) => Object.fromEntries(Object.entries(o).filter(([k]) => !keys.includes(k)));

let reg: EngRegister;
const load = async () => {
  reg = (await getEngScreen(HLT))!;
};

beforeAll(async () => {
  setDb(await openDatabase());
  await load();
}, 60_000);

/** Synthesis in the generator's shape. */
function synthesisShape(lang: Lang) {
  const v = synthesisScreenView(reg, makeT(lang), lang);
  return {
    kpis: v.kpis,
    from: v.from,
    matrix: v.matrix.map((r) => ({ label: r.label, cells: r.cells.map((c) => ({ bg: c.bg, items: c.items.map((i) => omit(i, 'key')) })) })),
    discCards: v.discCards.map((d) => ({ label: d.label, lead: d.lead, tools: d.tools, pct: d.pct, relText: d.relText, openText: d.openText, openColor: d.openColor })),
    gate: { cls: v.gate.cls, text: v.gate.text, items: v.gate.items.map((c) => ({ id: c.id, title: c.title, ruleLabel: c.ruleLabel, lead: c.lead, status: c.status, stClass: c.stClass, sevDot: c.sevDot })) },
    changes: v.changes.map((c) => omit(c, 'key')),
  };
}
const goldSynthesis = (lang: Lang, g: any) =>
  fixDeep(lang, {
    kpis: g.kpis.map((k: any) => ({ ...k, value: String(k.value) })),
    from: g.from,
    matrix: g.matrix,
    discCards: g.discCards.map((d: any) => ({ label: d.label, lead: d.lead, tools: d.tools, pct: d.pct, relText: d.relText, openText: d.openText, openColor: d.openColor })),
    gate: { cls: g.gate.cls, text: g.gate.text, items: g.gate.items.map((c: any) => omit(c, 'disc')) },
    changes: g.changes,
  });

/** Discipline screen in the generator's shape (every action allowed: the director). */
function disciplineShape(disc: Discipline, lang: Lang) {
  const v = disciplineScreenView(reg, disc, { filter: 'all', rights: { canEdit: true, canValidate: true }, todayIso: parisParts(new Date()).iso, parisDay }, makeT(lang), lang);
  return {
    head: v.head,
    kpis: v.kpis,
    inputs: v.inputs.map((r) => ({
      doc: r.doc, title: r.title, from: r.from, revText: r.revText, latestText: r.latestText, revColor: r.revColor, state: r.state, stClass: r.stClass, canConfirm: r.canConfirm,
      canImport: r.importHref !== null,
    })),
    // Delivery 7 (P-7c, R-106): `codexNote` (the Codex circuit line) is not a prototype value.
    docs: v.docs.map((d) => omit(d, 'docHref', 'codexNote')),
    outputs: v.outputs.map((o) => ({ id: o.id, name: o.name, toText: o.toText, source: o.source, genText: o.genText, stateText: o.stateText, stClass: o.stClass, canGen: o.canGen })),
    checks: v.checks.map((c) => ({ ...c })),
    chips: v.chips.map((c) => ({ label: c.label, count: String(c.count) })),
  };
}
const goldDiscipline = (lang: Lang, g: any) =>
  fixDeep(lang, {
    head: { icon: g.head.icon, lead: g.head.lead, tools: g.head.tools },
    kpis: g.kpis.map((k: any) => ({ ...k, value: String(k.value) })),
    inputs: g.inputs,
    docs: g.docs.map((d: any) => ({
      id: d.id, sub: `${d.title} · ${d.date} · ${d.by}`, rev: d.rev, status: d.status, stClass: d.stClass, toText: d.toText, canFreeze: d.canFreeze, canPropose: d.canPropose,
      proposeBlocked: d.proposeBlocked, blockedText: d.blockedText, canValidate: d.canValidate,
    })),
    outputs: g.outputs.map((o: any) => ({ id: o.id, name: o.name, toText: o.toText, source: o.source, genText: o.genText, stateText: o.stateText, stClass: o.stClass, canGen: o.canGen })),
    checks: g.checks.map((c: any) => ({
      id: c.id, title: c.title, detail: c.detail, meta: `${c.id} · ${c.ruleLabel} · ${c.ownerLabel} · ${c.lead}`, note: c.note, sevDot: c.sevDot, sevLabel: c.sevLabel, sevClass: c.sevClass,
      status: c.status, stClass: c.stClass, color: c.color, canAct: c.canAct,
    })),
    chips: g.chips.map((c: any) => ({ label: c.label, count: c.count })),
  });

describe('default state', () => {
  it.each(LANGS)('Synthesis (%s)', (lang) => {
    expect(synthesisShape(lang)).toEqual(goldSynthesis(lang, G[lang].default.synthesis));
  });

  for (const lang of LANGS)
    it.each(DISCS)(`discipline screen %s (${lang})`, (k) => {
      expect(disciplineShape(k, lang)).toEqual(goldDiscipline(lang, G[lang].default.disciplines[k]));
    });

  it.each(LANGS)('import wizard: header presets (%s)', (lang) => {
    for (const screen of ['eng', 'eng-process', 'eng-meca', 'eng-elec', 'eng-auto'] as EngScreen[]) {
      const m = importWizardModel(reg, primaryImportTarget(reg, screen)!, makeT(lang));
      const g = fixDeep(lang, G[lang].wizard.presets[screen].vals);
      expect({
        target: m.target, file: m.file, steps: m.steps.map((s) => s.label), tools: m.tools.map((t) => [t.label, t.disc]), map: m.map,
        stats: m.stats, deltas: m.deltas.map((d) => omit(d, 'key')),
      }).toEqual({
        target: g.target, file: g.file, steps: g.steps.map((s: any) => s.label), tools: g.tools.map((t: any) => [t.label, t.disc]), map: g.map,
        stats: g.stats, deltas: g.deltas,
      });
    }
  });

  it('template labels and screen strings: the prototype French, except the deliberate fixes', () => {
    const t = makeT('fr');
    for (const [en, fr] of Object.entries({ ...G.labels, ...G.extra } as Record<string, string>)) expect([en, t(en)]).toEqual([en, fix('fr', fr)]);
    expect(trFR('Sent back to tool · closes on next import')).toBe('Renvoyé vers l’outil · se clôt au prochain import');
  });
});

/**
 * P-7c = a (Delivery 7, R-106): "Validate release (PM)" starts the Codex approval circuit instead of releasing at once.
 * The prototype's immediate release is replayed as the PM's validation, the circuit's approvals recorded in Keystone (the
 * director on the approvers' behalf) and Codex's answer — released, the previous revision withdrawn — so the screens
 * still match the prototype's values after the step.
 */
async function validateThroughCodex(number: string): Promise<void> {
  await validateEngRelease(HLT, number, DIRECTOR);
  let rec = await getDocumentRecord(number);
  while (rec?.canApprove) {
    await recordDocumentDecision(number, { decision: 'approved' }, DIRECTOR);
    rec = await getDocumentRecord(number);
  }
  const r = rec!;
  const prev = /^[B-Z]$/.test(r.revision) ? String.fromCharCode(r.revision.charCodeAt(0) - 1) : null;
  await (await getDb()).transaction((tx) => applyCodexDocumentStates(tx, [{
    number, revision: r.revision, status: 'released', withdrawnRevision: prev, withdrawnOn: prev ? CODEX_TODAY_ISO : null,
    approvals: r.approvals.filter((a) => a.position > 0).map((a) => ({ step: a.position, signedOn: CODEX_TODAY_ISO })),
  }]));
}

/** The generator's sequence, replayed with the data-layer writers (actor: the director). */
const STEPS: Record<string, () => Promise<unknown>> = {
  'confirm meca PID-HLT-026': () => confirmEngInput(HLT, 'meca', 'PID-HLT-026', DIRECTOR),
  'resolve C-01': () => closeEngCheck(HLT, 'C-01', 'resolved', DIRECTOR),
  'send back C-03': () => closeEngCheck(HLT, 'C-03', 'sent_back', DIRECTOR),
  'import elec LST-INS-026': () => importEngList(HLT, { consumer: 'elec', documentNumber: 'LST-INS-026', toolPosition: 0 }, DIRECTOR),
  'freeze SCH-ELE-026': () => freezeEngDeliverable(HLT, 'SCH-ELE-026', DIRECTOR),
  'propose BOM-MEC-026': () => proposeEngRelease(HLT, 'BOM-MEC-026', DIRECTOR),
  'validate BOM-MEC-026': () => validateThroughCodex('BOM-MEC-026'),
  'generate O-01': () => generateEngOutput(HLT, 'O-01', DIRECTOR),
  'import auto LST-IO-026': () => importEngList(HLT, { consumer: 'auto', documentNumber: 'LST-IO-026', toolPosition: 2 }, DIRECTOR),
  'resolve C-02': () => closeEngCheck(HLT, 'C-02', 'resolved', DIRECTOR),
  'send back C-04': () => closeEngCheck(HLT, 'C-04', 'sent_back', DIRECTOR),
  'propose SCH-ELE-026': () => proposeEngRelease(HLT, 'SCH-ELE-026', DIRECTOR),
  'validate SCH-ELE-026': () => validateThroughCodex('SCH-ELE-026'),
  'generate O-03': () => generateEngOutput(HLT, 'O-03', DIRECTOR),
  'confirm elec LST-INS-026': () => confirmEngInput(HLT, 'elec', 'LST-INS-026', DIRECTOR),
  'import process GA-HLT-026': () => importEngList(HLT, { consumer: 'process', documentNumber: 'GA-HLT-026', toolPosition: 1 }, DIRECTOR),
  'propose FDS-HLT-026': () => proposeEngRelease(HLT, 'FDS-HLT-026', DIRECTOR),
};

describe('sequence replayed with the data-layer writers', () => {
  it('after every step: Synthesis, the discipline acted on and the badges, in EN and FR', async () => {
    expect(G.en.sequence.map((s: any) => s.name)).toEqual(Object.keys(STEPS));
    const { engNavBadgesOf } = await import('@/server/dal/eng-screen');
    for (let i = 0; i < G.en.sequence.length; i++) {
      const name = G.en.sequence[i].name as string;
      await STEPS[name]();
      await load();
      for (const lang of LANGS) {
        const g = G[lang].sequence[i];
        expect([name, lang, synthesisShape(lang)]).toEqual([name, lang, goldSynthesis(lang, g.synthesis)]);
        expect([name, lang, disciplineShape(g.disc, lang)]).toEqual([name, lang, goldDiscipline(lang, g.discipline)]);
        expect([name, engNavBadgesOf(reg)]).toEqual([name, g.badges]);
      }
    }
  }, 60_000);
});
